    # Create adjacency list for the tree
    tree = defaultdict(list)
    for i, (p, _) in enumerate(edges, start=1):
        tree[p].append(i)

    # Initialize the result array
    a = [0] * n

    # Check if the tree can be restored
    def check_restore(v, min_val, max_val):
        nonlocal a
        if a[v] == 0:
            # Find the possible value for the current vertex
            possible_values = []
            for val in range(min_val + 1, max_val):
                if all(a[u] != val for u in tree[v]):
                    possible_values.append(val)
            if not possible_values:
                return False
            a[v] = possible_values[0]

        # Check the count condition
        count = sum(1 for u in tree[v] if a[u] < a[v])
        if count != edges[v][1]:
